<script lang="ts">
  import { ws, gases, gasLabels, gasChannels, type Stage } from '../lib/sim.svelte'
  let tab = $state(0)
  let name = $state('')
  let kind = $state<'reduction' | 'oxidation'>('reduction')
  const blank = (): Stage => ({ name: '反应测定', duration_s: 60, temperature_c: 750, flows: Object.fromEntries(gases.map(g => [g, g === 'n2' ? 5 : 0])) as Stage['flows'] })
  let stages = $state<Stage[]>([blank()])
  async function save() {
    try { const saved = await ws.request<{id:number}>('sim_recipe_save', { name, kind, stages }); ws.notice = '配方版本已保存'; await ws.load(); await ws.loadRecipe(saved.id); tab = 1 } catch { /* shown */ }
  }
  async function open(id: number) { await ws.loadRecipe(id); tab = 1 }
  function copy() { if (!ws.selectedRecipe?.stages) return; name = ws.selectedRecipe.name; kind = ws.selectedRecipe.kind; stages = structuredClone(ws.selectedRecipe.stages); tab = 2 }
</script>
<p class="lead">配方按版本保存。七种气体映射六台 MFC；N₂ / Ar 共用 MFC-01，单次实验只选其一。</p>
<div class="tabs">{#each ['配方列表','配方详情','阶段编辑','旧库配方'] as label,i}<button class:active={tab === i} onclick={() => { tab = i; if (i === 3) void ws.loadLegacy() }}>{label}</button>{/each}</div>
{#if tab === 0}<section class="panel"><div class="panel-header"><h2>版本化配方</h2><button class="button primary" onclick={() => { name = ''; stages = [blank()]; tab = 2 }}>新建配方</button></div><div class="table-wrap"><table><thead><tr><th>名称</th><th>版本</th><th>实验类型</th><th>保存时间</th><th>操作</th></tr></thead><tbody>{#each ws.recipes as recipe}<tr><td><strong>{recipe.name}</strong></td><td>v{recipe.version}</td><td>{recipe.kind === 'reduction' ? '还原' : '氧化'}</td><td>{recipe.created_at?.slice(0,19)}</td><td><button class="text-button" onclick={() => open(recipe.id)}>查看阶段</button></td></tr>{:else}<tr><td colspan="5" class="empty">暂无配方</td></tr>{/each}</tbody></table></div></section>{/if}
{#if tab === 1}{#if ws.selectedRecipe}<section class="panel"><div class="panel-header"><h2>{ws.selectedRecipe.name} · v{ws.selectedRecipe.version}</h2><button class="button secondary" onclick={copy}>基于此版本编辑</button></div><div class="panel-body"><p>实验类型：{ws.selectedRecipe.kind === 'reduction' ? '还原' : '氧化'}</p><div class="stage-list">{#each ws.selectedRecipe.stages ?? [] as stage,i}<div class="stage-card"><h3>阶段 {i+1} · {stage.name}</h3><p>{stage.temperature_c} ℃ · {stage.duration_s} 秒</p><div class="gas-grid">{#each gases as gas}<span>{gasLabels[gas]} <b>{stage.flows[gas]}</b> L/min</span>{/each}</div></div>{/each}</div></div></section>{:else}<div class="empty-state"><h3>请选择配方</h3><button class="button secondary" onclick={() => tab = 0}>返回列表</button></div>{/if}{/if}
{#if tab === 2}<section class="panel"><div class="panel-header"><h2>阶段编辑</h2><span class="badge">保存为新版本</span></div><div class="panel-body"><div class="form-grid"><label>配方名称<input bind:value={name} maxlength="100"/></label><label>实验类型<select bind:value={kind}><option value="reduction">还原实验 · 禁用 O₂</option><option value="oxidation">氧化实验 · 禁用 CO / H₂ / CH₄</option></select></label></div><p class="muted">所有上限由 Python 服务端再次校验。参数仅用于仿真，不会发送到真实设备。</p>
  {#each stages as stage,i}<div class="stage-editor"><div class="panel-header"><h3>阶段 {i+1}</h3><button class="text-button" disabled={stages.length === 1} onclick={() => stages.splice(i,1)}>删除阶段</button></div><div class="form-grid"><label>名称<input bind:value={stage.name}/></label><label>时长 / 秒<input type="number" min="1" max="86400" bind:value={stage.duration_s}/></label><label>温度 / ℃<input type="number" min="20" max="1200" bind:value={stage.temperature_c}/></label></div><div class="gas-grid">{#each gases as gas}<label>{gasLabels[gas]} · {gasChannels[gas]}<input type="number" min="0" max={ws.settings?.limits[gas] ?? 20} step="0.1" disabled={(kind === 'reduction' && gas === 'o2') || (kind === 'oxidation' && ['co','h2','ch4'].includes(gas))} bind:value={stage.flows[gas]}/><small>上限 {ws.settings?.limits[gas] ?? '—'} L/min</small></label>{/each}</div></div>{/each}
  <div class="action-row"><button class="button secondary" onclick={() => stages.push(blank())}>添加阶段</button><button class="button primary" onclick={save}>校验并保存版本</button></div></div></section>{/if}
{#if tab === 3}<section class="panel"><div class="panel-header"><h2>导入的旧版配方</h2><span class="badge warn">仅查看 · 三气路来源</span></div><div class="table-wrap"><table><thead><tr><th>编号</th><th>名称</th><th>阶段数</th><th>来源指纹</th></tr></thead><tbody>{#each ws.legacyRecipes as recipe}<tr><td>#{recipe.id}</td><td>{recipe.name}</td><td>{recipe.steps.length}</td><td class="mono">{recipe.source_hash.slice(0,12)}</td></tr>{:else}<tr><td colspan="4" class="empty">暂无导入配方；可在系统设置中选择旧数据库</td></tr>{/each}</tbody></table></div></section>{/if}
